const research = $json.text;

if (!research) {
  throw new Error('GST Research Agent returned no research brief.');
}

const topicId = $('Get Selected GST Topic').item.json.topic_id;
const topicTitle = $('Get Selected GST Topic').item.json.topic_title;
const caseReference = $('Get Selected GST Topic').item.json.case_or_reference;
const court = $('Get Selected GST Topic').item.json.court_or_authority;

return [{
  json: {
    topic_id: topicId,
    topic_title: topicTitle,
    case_or_reference: caseReference,
    court_or_authority: court,

    verification_queries: [
      `"${caseReference}" judgment`,
      `"${caseReference}" "${court}"`,
      `"${caseReference}" Supreme Court appeal`,
      `"${caseReference}" review SLP`,
      `"${topicTitle}" GST`
    ],

    research_brief: research,

    verification_instruction:
      'Verify the legal position against primary sources wherever possible. ' +
      'Prioritise court judgments/orders, official legislation, CBIC notifications/circulars, ' +
      'and official government sources. Do not treat secondary articles as proof of a legal holding.'
  }
}];

const query = $json.query;

return [{
  json: {
    query,

    source_urls: [
      `https://www.sci.gov.in/`,
      `https://orissahighcourt.nic.in/`,
      `https://www.cbic.gov.in/`,
      `https://www.gst.gov.in/`,
      `https://www.indiacode.nic.in/`
    ],

    source_priority: 'PRIMARY'
  }
}];

const topics = $input.all();

const options = topics.map(item => {
  const id = item.json.topic_id;
  const title = item.json.topic_title;

  return `
    <a href="/webhook/gst-topic-selector?topic_id=${encodeURIComponent(id)}"
       style="display:block;padding:14px;margin:10px 0;
              border:1px solid #ddd;border-radius:8px;
              text-decoration:none;color:#222;">
      <strong>${id}</strong> — ${title}
    </a>
  `;
}).join('');

return [{
  json: {
    html: `
      <!DOCTYPE html>
      <html>
      <head>
        <meta charset="UTF-8">
        <title>MuniAI GST Topic Selector</title>
      </head>
      <body style="font-family:Arial;max-width:900px;margin:40px auto;padding:20px;">
        <h1>MuniAI — Select GST Topic</h1>
        <p>Select the topic for which you want to prepare a LinkedIn post.</p>
        ${options}
      </body>
      </html>
    `
  }
}];
